// Runs this package's `test` script under native V8 coverage and reports its original sources.
//
// Scope rule: the four entry modules (`index.js`, `standard.js`, `compact.js`, `detailed.js`), the three
// maintenance generators (`scripts/generate-index.mjs`, `scripts/optimize-flags.mjs`,
// `scripts/build-compact.mjs`) and this runner are the package's original code. Everything under `flags/`
// is generated by `scripts/generate-index.mjs` (per-code loader modules, the lazy loader maps and the
// eager URL map) and is excluded; the exclusion is only granted to files that carry the generator's
// banner, so hand-written code cannot hide there. The SVG and WebP assets are data, not JavaScript. Test
// files are excluded; the helper they share is real code that runs, so it is measured. Every other
// JavaScript file must be classified here, so a new script cannot silently leave the report.
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { runNodeCoverage } from '../../lyra-docs/scripts/lib/node-coverage.mjs';

export const GENERATED_BANNER = '// AUTO-GENERATED FILE. Do not edit by hand.\n';
export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const SCOPE = Object.freeze({
  label: '@aceshooting/lyra-flags',
  floor: 95,
  include: [
    'index.js', 'standard.js', 'compact.js', 'detailed.js',
    'scripts/build-compact.mjs', 'scripts/coverage.mjs', 'scripts/generate-index.mjs', 'scripts/optimize-flags.mjs',
    'scripts/test-support.mjs',
  ],
  exclude: [
    {
      pattern: /^flags\/.+\.js$/u,
      reason: 'generated by scripts/generate-index.mjs',
      verify: (name, text) => {
        if (!text.startsWith(GENERATED_BANNER)) throw new Error(`${name} sits in the generated tree without the generator banner`);
      },
    },
    { pattern: /^scripts\/test\.mjs$|\.test\.mjs$/u, reason: 'test' },
  ],
});

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exitCode = (await runNodeCoverage({ root: ROOT, ...SCOPE })).exitCode;
}
